// ============ Jable 视频书源 · 公共JS库 ============
// 只放不碰 java binding 的纯函数（jsLib 共享 scope 看不到 evalJS 注入的 java）。
// 线路真身 = source.setVariable(JSON)（跨环境共享）：{jbLine:"https://jable02.net", jbLines:"[...]", jbPage:"0", jbSpN:"123ms"}
function JB_getData() {
  var d; try { d = this.source.getVariable(); } catch (e) { d = null; }
  if (d === null || d === undefined || d === '') return {};
  try { return JSON.parse(String(d)); } catch (e) { return {}; }
}
function JB_saveData(d) {
  var s = JSON.stringify(d);
  try { this.source.setVariable(s); } catch (e) {}
  return s;
}
// 当前线路根（默认 jable02.net，来自发布页 Jable 条目首条）
function JB_line() {
  var d = JB_getData.call(this);
  var l = String(d.jbLine || 'https://jable02.net');
  if (l.indexOf('http') !== 0) l = 'https://jable02.net';
  return l.replace(/\/+$/, '');
}
function JB_base() { return JB_line.call(this); }
function JB_writeLine(line) {
  var d = JB_getData.call(this);
  d.jbLine = String(line).replace(/\/+$/, '');
  JB_saveData.call(this, d);
  try { this.source.put('jbLine', d.jbLine); } catch (e) {}
  return d.jbLine;
}
function JB_lineList() {
  var d = JB_getData.call(this);
  if (!d.jbLines) return [];
  try { return JSON.parse(String(d.jbLines)); } catch (e) { return []; }
}
function JB_storeLines(lines) {
  var d = JB_getData.call(this);
  d.jbLines = JSON.stringify(lines);
  JB_saveData.call(this, d);
  return lines;
}

