// ============ Jable 视频书源 · 登录/线路管理面板 ============
// loginUi <js> 与 action 共用本文件（SourceLoginDialog 拼 "$loginJS\n$buttonFunctionJS"）。
// ★用到 java 的函数必须放这里（jsLib 共享 scope 看不到 evalJS 注入的 java）。
// 发布页输入框名: pub；线路: jbLine / jbLines（jsLib JB_* 经 this.source 存取同一真身）
function JB_toast(s, long) {
  try { if (long) java.longToast(s); else java.toast(s); } catch (e) { try { java.toast('' + s); } catch (e2) {} }
}
function JB_reUi() {
  try { java.reLoginView(); } catch (e) { try { java.reLoginView(false); } catch (e2) { try { java.reUiView(false); } catch (e3) {} } }
}
function JB_hdrPanel() {
  return "{\"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36\", \"Accept-Language\": \"zh-CN,zh;q=0.9\"}";
}

// ---- 发布页 → Jable 线路池（java 函数必须在此；x99dh.github.io 静态导航 base64）----
function JB_fetchPub() {
  var navs = ['https://x99dh.github.io/', 'https://x99dh.pages.dev/'];
  for (var n = 0; n < navs.length; n++) {
    try {
      var r = java.connect(navs[n], JB_hdrPanel(), 15000);
      var b = r.body() + '';
      var m = b.match(/encodedData\s*=\s*'([^']+)'/);
      if (!m) continue;
      var j = decodeURIComponent(java.base64Decode(m[1]));
      var arr = JSON.parse(j);
      for (var i = 0; i < arr.length; i++) {
        if (String(arr[i].name) === 'Jable' && arr[i].urls) {
          var out = [];
          for (var k = 0; k < arr[i].urls.length; k++) {
            var u = String(arr[i].urls[k].url || '').replace(/\/enter\/?$/, '').replace(/\/+$/, '');
            if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
          }
          if (out.length) return {lines: out, def: String(arr[i].url || out[0]).replace(/\/enter\/?$/, '').replace(/\/+$/, ''), from: navs[n]};
        }
      }
    } catch (e) {}
  }
  return null;
}

// 并发测速（status.html 返回 2 字节 'ok' + callTime 判活），ms 写按钮，最快自动切换
function JB_pickFastest() {
  var list = JB_lineList.call(this);
  if (!list.length) return null;
  var best = -1, bestMs = 999999, tested = 0, lastErr = '', mode = '';
  var i, ms, txt, rs = null;
  try {
    var more = [];
    for (i = 0; i < list.length; i++) {
      more.push(list[i] + '/status.html?t=' + Date.now() + ',{"headers":' + JB_hdrPanel() + ',"retry":0}');
    }
    rs = java.ajaxAll(more, true);
    var n = (rs && (rs.length || (rs.size ? rs.size() : 0))) || 0;
    var rsOk = false;
    try {
      var ct0 = parseInt(rs[0].callTime(), 10);
      var bd0 = String(rs[0].body() || '');
