    } catch (eChk) { rsOk = false; }
    if (rsOk) {
      mode = 'ajaxAll';
      for (i = 0; i < n; i++) {
        ms = 999999; txt = '';
        try { ms = parseInt(rs[i].callTime(), 10); } catch (e) {}
        try { txt = String(rs[i].body() || ''); } catch (e2) {}
        if (txt.trim() !== 'ok' || ms > 15000 || ms < 0) ms = 999999;
        try { this.source.put('jbSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e9) {}
        if (ms < 15000) tested++;
        if (ms < bestMs) { bestMs = ms; best = i; }
      }
    } else { rs = null; }
  } catch (e) { lastErr = 'ajaxAll:' + String(e).substring(0, 40); rs = null; }
  if (!rs) {
    mode = 'connect';
    for (i = 0; i < list.length; i++) {
      ms = 999999; txt = '';
      try {
        var r = java.connect(list[i] + '/status.html?t=' + Date.now(), JB_hdrPanel(), 6000);
        var ct = 0; try { ct = parseInt(r.callTime(), 10); } catch (e3) {}
        try { txt = String(r.body() || ''); } catch (e4) {}
        if (txt.trim() === 'ok' && ct >= 0) ms = ct;
      } catch (e5) { lastErr = 'connect:' + String(e5).substring(0, 40); }
      try { this.source.put('jbSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e6) {}
      if (ms < 15000) tested++;
      if (ms < bestMs) { bestMs = ms; best = i; }
    }
  }
  try { this.source.put('jbDiag', 'mode=' + mode + ' tested=' + tested + ' best=' + best + ' err=' + lastErr); } catch (e7) {}
  if (best >= 0 && bestMs < 15000) {
    JB_writeLine.call(this, String(list[best]));
    return {best: best, line: String(list[best]), ms: bestMs, tested: tested};
  }
  return null;
}

// 🧭 一键从发布页获取网址路线（取回 Jable 18 条线路 + 自动测速选最快）
function JB_actionFetch() {
  JB_toast('🧭 正在解析 x99dh 发布页 Jable 线路…', true);
  try {
    var res = JB_fetchPub();
    if (!res || !res.lines || !res.lines.length) {
      JB_toast('❌ 未解析到线路，检查网络或稍后再试', true);
      return;
    }
    JB_storeLines.call(this, res.lines);
    var d = JB_getData.call(this);
    d.jbPage = '0';
    JB_saveData.call(this, d);
    JB_writeLine.call(this, String(res.def || res.lines[0]));
    JB_toast('✅ 获取 ' + res.lines.length + ' 条线路，正在测速选最快…', true);
