  d.jbPage = String((page + 1) % max);
  JB_saveData.call(this, d);
  JB_toast('📄 线路第 ' + (parseInt(d.jbPage, 10) + 1) + '/' + max + ' 页', false);
  JB_reUi();
}

// 🔍 检查登录状态（本站游客可看，探测当前线路可达性）
function JB_actionCheck() {
  JB_toast('🔍 正在检查当前线路…', true);
  try {
    var u = JB_base.call(this) + '/latest-updates/';
    var r = java.connect(u, JB_hdrPanel(), 15000);
    var b = r.body() + '';
    var ok = b.indexOf('video-img-box') >= 0;
    var ms = 0; try { ms = parseInt(r.callTime(), 10); } catch (e) {}
    if (ok) JB_toast('✅ 线路正常（游客可用，无登录）' + (ms ? ' ' + ms + 'ms' : ''), true);
    else if (b.length > 500) JB_toast('⚠️ 线路有响应但内容异常，建议测速换线', true);
    else JB_toast('⚠️ 线路异常，建议⏱测速换线', true);
  } catch (e) { JB_toast('❌ 检查失败：' + String(e).substring(0, 50), true); }
}

